    tiny: at('P', [0, 0], [0, 2]),
  },
  summer: {
    name: 'sunglasses',
    paint: { D: 'bg', F: 'accent' },
    small: [...run('D', 4, 1, 3), ...run('D', 4, 6, 8), ...run('D', 5, 1, 3), ...run('D', 5, 6, 8), ...at('F', [4, 4], [4, 5])],
    tiny: at('F', [0, 0], [0, 2]),
